"""Vector groups, coordinate changes and complete affine solution spaces."""
import manual_solutions as author
from matrix_workings import sp,L,reduce,determinant,inverse
from linear_algebra_chapter_two import visible,multiply
from linear_algebra_chapter_three import system,row_work,matrix_equation
def V(*cols):return sp.Matrix.hstack(*(sp.Matrix(c) for c in cols))
def put(n,steps,errors,solution=None):
 author.add('LA7',f'004-{n:03}',steps,errors,'检查每个向量系数、独立性、基础解系、全部自由变量及换基方向。')
 p=author.PATCHES[f'SRC-LA7-E004-{n:03}'];p['supersedes_computed_supplement']=True
 if solution is not None:p['solution']=solution
def example(n,steps,errors):
 author.add_example('LA7',n,steps,errors,'逐步消元或证明双向包含，检查基、维数、坐标与原向量反代。')
 author.PATCHES['SRC-LA7-X'+n]['supersedes_computed_supplement']=True
def representation(A,B,label):
 out=[f'**{label}。** 原生成向量按列排成A，目标按列排成B。找系数即解Ax=b；下列xᵢ是线性组合的系数，不是目标向量本来的标准坐标。']
 for j in range(B.cols):out+=system(A,B[:,j],'表示第'+str(j+1)+'个目标向量')
 return out
def column_basis(A,label,symbol='a',name='A'):
 F,pivots=A.rref();r=len(pivots);C=A[:,list(pivots)]
 out=row_work(A,label)
 out+=['主元位于原第'+('、'.join(str(j+1) for j in pivots) or '无')+'列，因此选取原矩阵对应列作最大无关组，不能用变换后的列代替原向量。原向量组秩为'+str(r)+'。']
 if pivots:out+=['所选原列矩阵为 $$C='+L(C)+'.$$']
 for j in range(A.cols):
  if j in pivots:continue
  coeff=sp.Matrix([F[i,j] for i in range(r)]);assert C*coeff==A[:,j]
  text='+'.join('('+L(c)+')'+symbol+'_{'+str(k+1)+'}' for c,k in zip(coeff,pivots)) or '0'
  out+=['第'+str(j+1)+'列在行最简形中的同一关系回到原列仍成立：$$'+symbol+'_{'+str(j+1)+'}='+text+'.$$直接将原列代入计算也相等，因为初等行变换可逆，保持全部列关系。']
 if r<A.cols:
  z=A.nullspace()[0];assert A*z==sp.zeros(A.rows,1)
  out+=['另一个相关性检查是取非零系数列 $$z='+L(z)+r',\quad '+name+r'z=0.$$秩小于列数，所以向量组线性相关。']
 else:out+=['秩等于向量个数，所以只有零系数才能组合成零，向量组线性无关。']
 return out
def transition(A,B,y,label):
 assert A.det()!=0 and B.det()!=0
 P=A.inv()*B;z=P.inv()*y;assert B*z==A*y
 out=[f'**{label}。** 采用教材约定B=AP，P各列是新基向量在旧基中的坐标。两个基矩阵均可逆，先解AP=B。']
 out+=matrix_equation(A,B,'求过渡矩阵，辅助未知X即P')
 out+=['因此 $$P='+L(P)+r'.$$同一个向量满足Ay=Bz=APz，所以旧坐标y=Pz，新坐标z=P⁻¹y。过渡矩阵本身与旧坐标到新坐标的乘数方向相反。']
 out+=inverse(P)[0]+multiply(P.inv(),y,'z')
 out+=['标准坐标反代：$$Bz='+L(B*z)+'=Ay.$$原向量保持不变，改变的只是坐标列。']
 return out

A=V([0,1,2,3],[3,0,1,2],[2,3,0,1]);B=V([2,1,1,2],[0,-2,1,1],[4,4,1,3])
put(1,representation(A,B,'B由A表示')+column_basis(A,'A的秩')+column_basis(B,'B的秩','b','B')+[r'B全部在A的列空间中，但B的空间维数2小于A的3，若A也全能由B表示就会迫使3≤2，矛盾。所以反向不可表示。'],[r'一组能由另一组表示不自动推出反向，需比较张成空间。',r'秩严格不同已能否定等价，不必逐一尝试所有反向方程。'])
A=V([0,1,1],[1,1,0]);B=V([-1,0,1],[1,2,1],[3,2,-1])
put(2,representation(A,B,'先证B由A表示')+[r'反向直接由前两目标的关系b₁=a₁−a₂、b₂=a₁+a₂，相加、相减得a₁=(b₁+b₂)/2，a₂=(b₂−b₁)/2。因此A、B互相可表示，向量组等价。',r'等价只要求张成同一空间，不要求向量数相同；本题一组2个、一组3个，后者有冗余向量。'],[r'两组等价不要求个数一样，也不要求每个向量相同。',r'反向可用B的一部分列，不必把三个都用上。'])
put(3,column_basis(V([-1,3,1],[2,1,0],[1,4,1]),'第（1）组')+column_basis(V([2,3,0],[-1,4,0],[0,0,2]),'第（2）组'),[r'三个向量在三维空间中仍可能相关，须检查秩或行列式。',r'找到非平凡关系足以证相关；无关则要证明只有零关系。'])
a=sp.Symbol('a');A=V([a,1,1],[1,a,-1],[1,-1,a])
put(4,[r'将三向量排成3阶列矩阵，相关当且仅当行列式为0。']+determinant(A)+[r'因式分解为(a−2)(a+1)²，故相关参数恰为a=2或−1，其余行列式非零、无关。',r'a=2时−a₁+a₂+a₃=0；a=−1时a₂=a₃=−a₁，都给非平凡关系，作为根的反代核验。'],[r'行列式为0判相关不要求所有列都零。',r'重根−1仍只是一种参数值，不重复列作两个答案。'])
put(5,[r'矩阵aaᵀ的第j列为aⱼa，bbᵀ的第j列为bⱼb，因此A的第j列是aⱼa+bⱼb，全部属于span{a,b}。',r'列空间包含给R(A)≤dim span{a,b}≤2，证明第（1），不要求a、b非零或无关。',r'若a、b相关，这个张成空间维数至多1，所以第（2）R(A)≤1；二者全0时A=0、秩0，也包含在不等式中。不能为了作比例表示就除以可能为0的向量或分量。'],[r'是秩至多2或1，不是必等于；零向量必须包含在讨论内。',r'外积的第j列由标量分量乘整个向量，不是逐元素平方组成一个向量。'])
put(6,[r'相关条件给不全为零x、y，使x(a₁+b)+y(a₂+b)=0，即xa₁+ya₂+(x+y)b=0。',r'若x+y=0，则y=−x，得到x(a₁−a₂)=0。a₁、a₂无关意味着a₁−a₂非零，只能x=y=0，与所选系数矛盾。因此x+y≠0，可合法相除。',r'令c=−x/(x+y)，则b=ca₁−(1+c)a₂。反向核查a₁+b=(1+c)(a₁−a₂)、a₂+b=c(a₁−a₂)，两者同方向，必相关（包括其中为零的c=0、−1情况）。'],[r'除以x+y前要先排除它为0。',r'c=0或−1不应删去，产生一个零向量仍符合相关。'])
put(7,[r'相关组分别只要求各自存在一组非零系数关系，这两组关系可以使用不同系数，不能自动在逐项相加后保留。',r'取二维e₁=(1,0)ᵀ、e₂=(0,1)ᵀ，令a₁=e₁、a₂=0，b₁=0、b₂=e₂。两个原组均含零向量，故都相关。',r'相加组为e₁、e₂。若xe₁+ye₂=0，比较坐标得x=y=0，所以无关，满足前提却违反“必相关”的结论。因此不一定。'],[r'原组分别相关并不能保证存在同一组系数同时把它们消掉。',r'反例应同时核对两原组相关、相加组无关。'])
put(8,[r'第（1）a₁=e₁、a₂=0为相关组，因为0·a₁+1·a₂=0；但a₁不能由唯一剩下的零向量表示。相关只保证至少某个系数非零对应向量可由其余表示，不保证指定a₁。',r'第（2）取m=1，a₁=e₁、b₁=−e₁，同一非零系数λ₁=1使两和相加为0；但两个单向量组各只有非零向量，都无关。总和的相消不能推出各自为0。',r'第（3）取m=1，a₁=0、b₁=e₁。λ₁(a₁+b₁)=0仅λ₁=0，但a组单零向量相关，故“各组都无关”失败，b组无关不挽救结论。',r'第（4）令(a₁,a₂)=(e₁,0)，(b₁,b₂)=(0,e₁)。前一组零关系要求λ₁=0，后一组要求λ₂=0，要两者同时成立只能全0；但两原组各自都相关。因此不存在所称共同非平凡系数。'],[r'第（2）、（3）的条件只控制逐项和向量组，不分别控制两组。',r'第（4）的“同一组系数”比两组各自存在不同关系强得多。'])
put(9,[r'观察四个b向量的循环相邻和，取交替符号系数1、−1、1、−1，而不是尝试求所有aᵢ的坐标。',r'b₁−b₂+b₃−b₄=(a₁+a₂)−(a₂+a₃)+(a₃+a₄)−(a₄+a₁)=0，每个a的系数恰相消。',r'这组系数并非全0，按线性相关定义立即得到b组相关；无论原a组怎样都成立，不需要先假定a组无关。'],[r'证相关只需一组非平凡系数，不能把它误要求为唯一关系。',r'四个循环和的交替符号是抵消关键。'])
put(10,[r'设∑cᵢbᵢ=0，代bᵢ=a₁+⋯+aᵢ。a₁系数为c₁+⋯+c_n，a₂系数为c₂+⋯+c_n，依次a_n系数c_n。',r'a组无关，全部这些尾和必须为0。最后一个先给c_n=0，倒数第二个给c_{n−1}=0，继续逆推到c₁=0，所以b组无关。',r'矩阵写法B=AK，K为对角元1的上三角阵，detK=1可逆。又a₁=b₁、aᵢ=bᵢ−b_{i−1}，反向差分也表明两个向量组等价，因而同秩n。'],[r'把系数按每个aᵢ汇总时是尾和，不是只保留对应cᵢ。',r'证明无关要由任意零组合推出全部系数0。'])
