steps=[r'以无关的a₁、a₂、a₃作参考，b组写B=AK。由于A列满秩，Bz=0等价于Kz=0，所以只需检查下面三个实际系数矩阵；不需要知道a的具体坐标。']
for i,K in enumerate(Ks,1):steps+=['第'+str(i)+'问的系数矩阵 $$K='+L(K)+r',\quad\det K='+L(K.det())+'.$$']+column_basis(K,'第'+str(i)+'问的系数列组','k','K')
put(11,steps,[r'每个b的三个a系数应排为K的一列，不是随意排一行。',r'第三组存在b₁−b₂+b₃=0，前两组则须由非零行列式判无关。'])
put(12,[r'写B=AK，A由无关的s列组成，所以A是列满秩。对任意r维系数z，Bz=0⇔A(Kz)=0；A的核只有零向量，进一步等价于Kz=0。',r'因此B组无关（只有零z使Bz=0）当且仅当K只有零齐次解，即K的r列无关、秩r。两个方向用的是同一个零解等价，而非只证一边。',r'若r>s，s×r的K不可能秩r，此时B在s维张成空间中也不可能有r个独立向量，结论仍一致。A不必方阵，不应直接使用A⁻¹。'],[r'关键条件是a组无关；若去掉此条件，K列满秩也可能被A压成相关组。',r'K的列数是r，判据应为R(K)=r，而不是s。'])
