put(14,sum((column_basis(A,'第'+str(i)+'个矩阵的列组') for i,A in enumerate(visible('E004-014'),1)),[]),[r'行变换保持列间系数关系，但不会保持原列的具体坐标。',r'主元列对应索引要回原矩阵取列，不能直接复制行最简形主元列作答案。'])
put(15,[r'后两个固定向量u=(1,2,1)ᵀ、v=(2,3,1)ᵀ的前两分量二阶子式3−4=−1非零，故它们独立，全部四向量的秩至少2。',r'u、v都满足平面方程−x+y−z=0，所以二者张成的二维空间正是y=x+z。秩要仍为2，前两个向量也必须在这个平面上。',r'(a,3,1)要求3=a+1，得a=2；(2,b,3)要求b=2+3，得b=5。反向这两个值使四向量全在同一二维平面，而u、v仍独立，故秩恰2，条件充分必要。'],[r'秩2不只是某个3阶子式为0，要保证所有四向量落在同一二维空间。',r'固定的u、v独立已排除秩1，不必再猜是否可能更低。'])
put(16,[r'R(a₁,a₂)=R(a₁,a₂,a₃)=2，说明a₃在span{a₁,a₂}中；而R(a₁,a₂,a₄)=3说明a₄不在此空间。',r'若新向量2a₃−3a₄在span{a₁,a₂}中，由a₃也在其中，可移项a₄=(2/3)a₃−(1/3)(2a₃−3a₄)也在其中，矛盾。',r'所以新向量加入原独立二向量后增加一个独立方向，D的秩为3。这依赖a₄的系数−3非零，不能将它忽略。'],[r'a₃可以被前两向量消去，但a₄的非零系数会带来新方向。',r'新组只有3列，秩最多3，证不在原空间即可。'])
put(17,[r'将n个n维向量排为n阶列矩阵A。若它们无关，则rankA=n、detA非零，对任意b可取系数x=A⁻¹b，故任意n维向量都可由它们表示。',r'反向假设每个b都能表示，特别是每个标准基eⱼ都在A列空间中。这些eⱼ张成整个Rⁿ，所以A列空间维数至少n，又只有n行，必为n，故列无关。',r'两方向证明“n个”和“n维”相匹配的重要性：一般多于n个生成向量也可张成全空间，却会相关；本题恰有n个才得到基的等价刻画。'],[r'能表示任意向量与只会表示某一个b不是同一强度。',r'向量个数n与空间维数n相等是充分必要条件的关键。'])
put(18,[r'a₁非零使单向量组a₁无关，而整个组相关，所以存在使前k个向量首次相关的最小k，且k≥2。前k−1个仍无关。',r'取前k个的非平凡关系∑_{i=1}^k cᵢaᵢ=0。若c_k=0，就变成前k−1个的非平凡关系，与其无关矛盾，因此c_k≠0。',r'合法除以c_k，移项得到 $a_k=-\sum_{i=1}^{k-1}(c_i/c_k)a_i$。这就是所求的某个后续向量能由其前面向量表示；并不保证每个a_k都能如此。'],[r'首次相关的最小索引保证最后系数非零。',r'a₁≠0排除第一个向量自身就是零的例外，否则k可能为1。'])
put(19,[r'每个βᵢ按定义是原a向量之和，所以β组可由a组表示。反向设S=∑aᵢ，βᵢ=S−aᵢ；将n式相加得∑βᵢ=(n−1)S。',r'n≥2时可除以n−1，得S=(∑βᵢ)/(n−1)，再代回 $a_i=\frac1{n-1}\sum_j\beta_j-\beta_i$。因此a组也可由β组表示，双方等价。',r'若原题允许n=1，则β₁为空和0；它与单向量a₁只有在a₁=0时等价。所以一般结论必须补n≥2这个条件，而不能在n=1时继续使用除法。'],[r'n−1作为分母前必须保证n≥2。',r'向量组等价指互相可表示，不要求各βᵢ等于相应aᵢ。'])
put(20,[r'由y=Ax、z=Ay=A²x，P=(x,y,z)列无关，可逆。AP三列分别为y、z、Az=A³x=3y−z。',r'在基P中，y坐标(0,1,0)ᵀ，z坐标(0,0,1)ᵀ，3y−z坐标(0,3,−1)ᵀ，按列排得 $B=\begin{pmatrix}0&0&0\\1&0&3\\0&1&-1\end{pmatrix}$，于是AP=PB。',r'右乘P⁻¹得A=PBP⁻¹，因此|A|=|B|。B首行全0，行列式0，故|A|=0。给定P可逆来自原三向量独立，不能在没有该条件时约去|P|。'],[r'每个AP列的基坐标放B的一列，不能转成一行。',r'P可逆不意味着A可逆；本题恰推出A奇异。'])
put(21,[r'V₁含零向量。若u、v各坐标和0，则u+v的坐标和仍0；任意实数c乘u的坐标和c×0=0，所以对加法与数乘封闭，是Rⁿ的子空间。',r'V₂不含零向量，因为零坐标和为0而非1，仅这一点已足否定向量空间。还可取v∈V₂，则2v的坐标和2，不在V₂，数乘不封闭。',r'坐标和等于1刻画一个仿射平面，和等于0才通过原点；两个集合形式仅差常数，却有不同的线性结构。'],[r'向量空间必须含0；非零右端的线性约束一般不满足。',r'不能只验证加法而忽略数乘，0倍也必须留在集合中。'])
